// Turns each due rule into one read-only SQL statement. Identifiers are validated and quoted;
// free-text clauses (where_clause, custom_sql) are screened. The read-only database role is the real safety net.
const IDENT = /^[A-Za-z_][A-Za-z0-9_$]{0,62}$/;
const qi = s => { const t = String(s).trim(); if (!IDENT.test(t)) throw new Error('invalid identifier "' + t.slice(0, 40) + '"'); return '"' + t + '"'; };
const qt = s => { const p = String(s).trim().split('.'); if (p.length > 2) throw new Error('table must be "table" or "schema.table"'); return p.map(qi).join('.'); };
const BAD = /;|--|\/\*|\*\/|\\|\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|copy|call|do|execute|vacuum|analyze|lock|listen|notify|set|reset|into|refresh|comment|reindex|cluster|pg_\w*|lo_\w*|dblink\w*)\b/i;
const screen = (text, field, allowSelect) => {
  const t = String(text).trim();
  if (!t || t.length > 1000) throw new Error(field + ' must be 1-1000 characters');
  if (BAD.test(t)) throw new Error(field + ' contains a forbidden keyword or character');
  if (!allowSelect && /\b(select|union|with)\b/i.test(t)) throw new Error(field + ' must be a plain condition (no subqueries)');
  if ((t.match(/'/g) || []).length % 2 || (t.match(/"/g) || []).length % 2) throw new Error(field + ' has unbalanced quotes');
  let depth = 0;
  for (const ch of t) { if (ch === '(') depth++; else if (ch === ')') { depth--; if (depth < 0) break; } }
  if (depth !== 0) throw new Error(field + ' has unbalanced parentheses');
  return t;
};
const posInt = (v, f) => { const n = Number(v); if (!Number.isInteger(n) || n < 1 || n > 525600) throw new Error(f + ' must be a whole number between 1 and 525600'); return n; };

return $input.all().map(({ json: r }) => {
  const out = { ...r, sql: null, config_error: null };
  try {
    const id = Number(r.id);
    if (!Number.isInteger(id) || id < 1) throw new Error('bad rule id');
    const w = r.where_clause ? screen(r.where_clause, 'where_clause', false) : null;
    const where = w ? ' WHERE (' + w + ')' : '';
    let inner;
    switch (r.kind) {
      case 'row_count':
        inner = 'SELECT count(*)::float8 AS value FROM ' + qt(r.table_name) + where; break;
      case 'freshness_minutes':
        inner = 'SELECT (EXTRACT(EPOCH FROM (now() - max(' + qi(r.column_name) + '))) / 60)::float8 AS value FROM ' + qt(r.table_name) + where; break;
      case 'null_pct':
        inner = 'SELECT (CASE WHEN count(*) = 0 THEN 0 ELSE 100.0 * count(*) FILTER (WHERE ' + qi(r.column_name) + ' IS NULL) / count(*) END)::float8 AS value FROM ' + qt(r.table_name) + where; break;
      case 'duplicate_count': {
        const keys = String(r.key_columns).split(',').map(s => s.trim()).filter(Boolean);
        if (!keys.length || keys.length > 5) throw new Error('key_columns needs 1-5 columns');
        inner = 'SELECT count(*)::float8 AS value FROM (SELECT 1 FROM ' + qt(r.table_name) + where + ' GROUP BY ' + keys.map(qi).join(', ') + ' HAVING count(*) > 1) d'; break;
      }
      case 'window_count': {
        const n = posInt(r.window_minutes, 'window_minutes');
        inner = 'SELECT count(*)::float8 AS value FROM ' + qt(r.table_name) + ' WHERE ' + qi(r.column_name) + ' >= now() - (' + n + ' * interval \'1 minute\')' + (w ? ' AND (' + w + ')' : ''); break;
      }
      case 'custom_sql': {
        const s = screen(r.custom_sql, 'custom_sql', true);
        if (!/^(select|with)\b/i.test(s)) throw new Error('custom_sql must start with SELECT or WITH');
        inner = 'SELECT (c.value)::float8 AS value FROM (' + s + ') c'; break;
      }
      default: throw new Error('unknown kind "' + r.kind + '"');
    }
    // always exactly one row: a scalar sub-select yields NULL when the inner query returns nothing
    out.sql = 'SELECT ' + id + '::int AS rule_id, (SELECT v.value FROM (' + inner + ') v LIMIT 1) AS value';
  } catch (e) {
    out.config_error = String(e.message).slice(0, 200);
    out.sql = 'SELECT ' + (Number(r.id) | 0) + '::int AS rule_id, NULL::float8 AS value';
  }
  return { json: out };
});

// Compares each measured value with its thresholds and, when anomaly_k is set, with the recent history (median / MAD).
const builds = $('Build Check Query').all().map(i => i.json);
const fmt = x => Number.isInteger(x) ? String(x) : x.toFixed(2);
const median = a => { const s = [...a].sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const clean = v => String(v).replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);
const num = v => (v === null || v === undefined || v === '') ? null : Number(v);
const out = [];
$input.all().forEach((it, i) => {
  const j = it.json || {};
  const b = (j.rule_id !== undefined && j.rule_id !== null) ? builds.find(x => Number(x.id) === Number(j.rule_id)) : builds[i];
  if (!b) return;
  const res = status => ({ json: { rule_id: Number(b.id), status: status.s, value: status.v === undefined ? null : status.v, detail: status.d } });
  if (b.config_error) { out.push(res({ s: 'error', d: 'Invalid rule: ' + clean(b.config_error) })); return; }
  if (j.error) {
    const m = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    out.push(res({ s: 'error', d: 'Check could not run: ' + clean(m) })); return;
  }
  const v = num(j.value);
  if (v === null || !Number.isFinite(v)) {
    out.push(b.kind === 'freshness_minutes' ? res({ s: 'fail', d: 'No rows to measure freshness' }) : res({ s: 'error', d: 'The check returned no value' }));
    return;
  }
  const min = num(b.min_value), max = num(b.max_value), k = num(b.anomaly_k);
  const reasons = [];
  let note = '';
  if (min !== null && v < min) reasons.push('value ' + fmt(v) + ' is below the minimum ' + fmt(min));
  if (max !== null && v > max) reasons.push('value ' + fmt(v) + ' is above the maximum ' + fmt(max));
  if (k !== null) {
    const hist = (Array.isArray(b.history) ? b.history : []).map(Number).filter(Number.isFinite);
    if (hist.length >= 10) {
      const med = median(hist), mad = median(hist.map(h => Math.abs(h - med)));
      const scale = mad > 0 ? 1.4826 * mad : Math.max(Math.abs(med) * 0.1, 1);
      const z = Math.abs(v - med) / scale;
      if (z > k) reasons.push('anomaly: ' + fmt(v) + ' vs typical ' + fmt(med) + ' (score ' + z.toFixed(1) + ' > ' + k + ')');
    } else note = ' (learning baseline: ' + hist.length + '/10 samples)';
  }
  out.push(reasons.length ? res({ s: 'fail', v, d: reasons.join('; ') }) : res({ s: 'ok', v, d: 'value ' + fmt(v) + note }));
});
return out;

const TZ = 'Asia/Jakarta';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = v => { const d = new Date(v); return isNaN(d) ? '-' : new Intl.DateTimeFormat('en-GB', { timeZone: TZ, day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).format(d); };
const dur = ms => { const m = Math.max(0, Math.round(ms / 60000)); if (m < 60) return m + 'm'; const h = Math.floor(m / 60); if (h < 48) return h + 'h ' + (m % 60) + 'm'; return Math.floor(h / 24) + 'd ' + (h % 24) + 'h'; };
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.incident_id) continue;
  const crit = r.severity === 'critical';
  let text, buttons = false;
  if (r.event === 'recovered') {
    const open = r.resolved_at && r.opened_at ? ' after ' + dur(new Date(r.resolved_at) - new Date(r.opened_at)) : '';
    text = '✅ <b>Recovered</b>: ' + esc(r.name) + '\nBack to normal' + open + '.\nIncident #' + r.incident_id;
  } else {
    const again = Number(r.notify_count) > 0;
    text = (crit ? '🔴 <b>CRITICAL</b>' : '🟠 <b>WARNING</b>') + (again ? ' (reminder)' : '') + ': ' + esc(r.name) + '\n' + esc(r.summary) +
      '\nOpen since ' + when(r.opened_at) + ', seen ' + r.occurrences + (Number(r.occurrences) === 1 ? ' time' : ' times') + '\nIncident #' + r.incident_id;
    buttons = true;
  }
  out.push({ json: { incident_id: Number(r.incident_id), text, has_buttons: buttons } });
}
return out;

const ALLOWED_USER_IDS = ['REPLACE_WITH_TELEGRAM_USER_ID'];   // who may acknowledge or snooze. Fail closed: the placeholder authorizes nobody.
const cq = $input.first().json.callback_query;
if (!cq) return [{ json: { authorized: false, query_id: null } }];
const m = /^dq:(ack|snz1|snz24):(\d{1,9})$/.exec(String(cq.data || ''));
const fromId = String(cq.from && cq.from.id);
const authorized = !!m && !!cq.message && ALLOWED_USER_IDS.includes(fromId);
return [{ json: {
  authorized,
  query_id: cq.id,
  action: m ? (m[1] === 'ack' ? 'ack' : 'snooze') : null,
  hours: m ? (m[1] === 'snz1' ? 1 : m[1] === 'snz24' ? 24 : 0) : 0,
  incident_id: m ? Number(m[2]) : null,
  decided_by: (cq.from && cq.from.username ? String(cq.from.username) + ' ' : '') + '(' + fromId + ')',
  chat_id: cq.message ? cq.message.chat.id : null,
  message_id: cq.message ? cq.message.message_id : null,
  orig_text: cq.message && typeof cq.message.text === 'string' ? cq.message.text : ''
} }];

const TZ = 'Asia/Jakarta';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = v => { const d = new Date(v); return isNaN(d) ? '-' : new Intl.DateTimeFormat('en-GB', { timeZone: TZ, day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).format(d); };
const dur = ms => { const m = Math.max(0, Math.round(ms / 60000)); if (m < 60) return m + 'm'; const h = Math.floor(m / 60); if (h < 48) return h + 'h ' + (m % 60) + 'm'; return Math.floor(h / 24) + 'd ' + (h % 24) + 'h'; };
const ctx = $('Parse Callback').first().json;
const r = $input.first().json || {};
let line, toast;
switch (r.outcome) {
  case 'acked': line = '✅ Acknowledged by ' + esc(ctx.decided_by); toast = 'Acknowledged'; break;
  case 'snoozed': line = '😴 Snoozed until ' + when(r.snooze_until) + ' by ' + esc(ctx.decided_by); toast = 'Snoozed for ' + ctx.hours + 'h'; break;
  case 'not_open': line = 'ℹ️ Already handled or resolved'; toast = 'Already handled or resolved'; break;
  default: line = 'ℹ️ Incident no longer exists'; toast = 'Incident not found';
}
return [{ json: { chat_id: ctx.chat_id, message_id: ctx.message_id, query_id: ctx.query_id, toast,
  text: esc(ctx.orig_text) + '\n\n' + line } }];

const deleted = $('Cleanup Old Results').first().json.deleted;
const TZ = 'Asia/Jakarta';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = v => { const d = new Date(v); return isNaN(d) ? '-' : new Intl.DateTimeFormat('en-GB', { timeZone: TZ, day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).format(d); };
const dur = ms => { const m = Math.max(0, Math.round(ms / 60000)); if (m < 60) return m + 'm'; const h = Math.floor(m / 60); if (h < 48) return h + 'h ' + (m % 60) + 'm'; return Math.floor(h / 24) + 'd ' + (h % 24) + 'h'; };
const r = { ...(($input.first().json || {}).report || {}), deleted };
const L = [];
const rules = Number(r.rules || 0), failing = Number(r.failing || 0);
L.push((failing ? '🔴' : '🟢') + ' <b>Data quality report</b>');
L.push('Rules: ' + rules + ' active, ' + failing + ' failing, ' + Number(r.snoozed || 0) + ' snoozed');
const c = Number(r.checks_24h || 0), f = Number(r.fails_24h || 0);
L.push('Last 24h: ' + c + ' checks, ' + (c ? ((c - f) / c * 100).toFixed(1) : '0') + '% passed');
if (Number(r.stale || 0) > 0) L.push('⚠️ ' + r.stale + ' rule(s) have not run on time. Is the check workflow active?');
if (Number(r.never_run || 0) > 0) L.push('ℹ️ ' + r.never_run + ' rule(s) have never run yet');
const inc = Array.isArray(r.open_incidents) ? r.open_incidents : [];
if (inc.length) {
  L.push('', '<b>Open incidents</b>');
  for (const i of inc) L.push((i.severity === 'critical' ? '🔴' : '🟠') + ' #' + i.id + ' ' + esc(i.rule) + (i.status === 'acked' ? ' (acked)' : '') + ' since ' + when(i.opened_at) + '\n    ' + esc(i.summary));
} else L.push('', 'No open incidents.');
const noisy = Array.isArray(r.noisiest) ? r.noisiest : [];
if (noisy.length) { L.push('', '<b>Most failures (24h)</b>'); for (const n of noisy) L.push('• ' + esc(n.rule) + ': ' + n.fails + ' of ' + n.checks); }
if (Number(r.deleted || 0) > 0) L.push('', 'Cleanup: removed ' + r.deleted + ' old results');
return [{ json: { text: L.join('\n').slice(0, 3900) } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
